space-complexity.pseudocode:
def sum_rec(a, n):  # 스택 깊이 n → 보조 공간 O(n)
    if n == 0:
        return 0
    return a[n - 1] + sum_rec(a, n - 1)

def sum_iter(a):  # 변수만 사용 → 보조 공간 O(1)
    total = 0
    for x in a:
        total += x
    return total

def fib(n):  # DP 테이블 O(n) 대신 직전 두 값만 → O(1)
    prev, cur = 0, 1
    for _ in range(n):
        prev, cur = cur, prev + cur
    return prev

spanning-tree.pseudocode:
def bfs_spanning_tree(graph, start):
    visited = {start}
    queue = [start]
    tree = []  # 신장 트리 간선
    while queue:
        u = queue.pop(0)
        for v in graph[u]:
            if v not in visited:  # 처음 만나는 정점만 → 사이클 없음
                visited.add(v)
                tree.append((u, v))
                queue.append(v)
    return tree  # 연결 그래프면 간선 수 = V - 1

spn-structure.pseudocode:
def substitute(s, sbox):  # 4비트 S-박스 4개 병렬
    out = 0
    for i in range(4):
        out |= sbox[(s >> 4 * i) & 0xF] << 4 * i
    return out

def permute(s, perm):  # 비트 전치(P-박스)
    out = 0
    for i in range(16):
        if (s >> i) & 1:
            out |= 1 << perm[i]
    return out

def spn_encrypt(x, keys, sbox, perm):
    nr = len(keys) - 1  # 라운드 수, 키는 nr+1개
    for r in range(nr - 1):
        x = substitute(x ^ keys[r], sbox)  # 키 혼합 → 혼돈
        x = permute(x, perm)  # 확산
    x = substitute(x ^ keys[nr - 1], sbox)  # 마지막: 전치 생략
    return x ^ keys[nr]  # 최종 키 화이트닝
